--
-- Table structure for table `historial_cambios_nota`
--

DROP TABLE IF EXISTS `historial_cambios_nota`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `historial_cambios_nota` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_historial` int NOT NULL,
  `id_docente` int DEFAULT NULL,
  `campo` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  `valor_anterior` decimal(5,2) DEFAULT NULL,
  `valor_nuevo` decimal(5,2) DEFAULT NULL,
  `motivo` text CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci,
  `fecha` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_hcn_hist` (`id_historial`),
  KEY `fk_hcn_doc` (`id_docente`),
  CONSTRAINT `fk_hcn_doc` FOREIGN KEY (`id_docente`) REFERENCES `docente` (`id_docente`) ON DELETE SET NULL,
  CONSTRAINT `fk_hcn_hist` FOREIGN KEY (`id_historial`) REFERENCES `historial` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1407 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

