--
-- Table structure for table `inscripcion`
--

DROP TABLE IF EXISTS `inscripcion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inscripcion` (
  `id` int NOT NULL AUTO_INCREMENT,
  `ci_est` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci NOT NULL,
  `cod_asig` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci NOT NULL,
  `id_sec` int NOT NULL,
  `fecha` date NOT NULL,
  `gestion` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci DEFAULT NULL,
  `turno` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci NOT NULL,
  `grupo` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci NOT NULL,
  `tipo` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci NOT NULL DEFAULT 'Normal',
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `estado_final` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci DEFAULT 'EN PROCESO',
  `observaciones` text CHARACTER SET utf8mb4 COLLATE utf8mb4_spanish_ci,
  `id_paralelo` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_inscripcion_est_mat_gestion` (`ci_est`,`cod_asig`,`gestion`),
  KEY `fk_ins_estudiante` (`ci_est`),
  KEY `fk_ins_asignatura` (`cod_asig`),
  KEY `fk_ins_secretaria` (`id_sec`),
  KEY `fk_ins_paralelo` (`id_paralelo`),
  CONSTRAINT `fk_ins_asignatura` FOREIGN KEY (`cod_asig`) REFERENCES `asignatura` (`codigo`),
  CONSTRAINT `fk_ins_estudiante` FOREIGN KEY (`ci_est`) REFERENCES `estudiante` (`ci`),
  CONSTRAINT `fk_ins_paralelo` FOREIGN KEY (`id_paralelo`) REFERENCES `paralelo` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ins_secretaria` FOREIGN KEY (`id_sec`) REFERENCES `secretaria` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=763 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_spanish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

